-- =============================================================================
-- MindSpace V1: identity, refresh sessions, preferences, consent log
--
-- Conventions used by every migration:
--   * UUID primary keys (java.util.UUID in JPA), generated by gen_random_uuid().
--   * Instants are TIMESTAMPTZ (java.time.Instant / OffsetDateTime).
--   * Local calendar dates are DATE (java.time.LocalDate); the IANA timezone
--     used to derive them is stored alongside.
--   * Enumerations are VARCHAR + CHECK (not PostgreSQL ENUM types) so that
--     @Enumerated(EnumType.STRING) and Hibernate schema validation work and new
--     values can be added by an ordinary migration.
--   * Scores and durations are INTEGER (not SMALLINT) so Java int fields pass
--     Hibernate's schema validation without column-type mismatches.
--   * `version` columns support JPA @Version optimistic locking.
--   * Every user-owned row carries user_id with ON DELETE CASCADE, so deleting
--     a user removes all of their data (documented retention policy).
-- =============================================================================

-- Keeps updated_at correct even for writes that bypass JPA auditing.
CREATE FUNCTION set_updated_at() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
END;
$$;

CREATE TABLE users (
    id                  UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Stored lower-cased and trimmed; the application normalises before insert
    -- and the CHECK below rejects anything that slips through.
    email               VARCHAR(320) NOT NULL,
    display_name        VARCHAR(100) NOT NULL,
    -- BCrypt hash only (60 chars today); never a plaintext password.
    password_hash       VARCHAR(100) NOT NULL,
    -- IANA zone id (e.g. Asia/Kolkata); validated against java.time.ZoneId in
    -- the application. All "local date" logic uses this value.
    timezone            VARCHAR(64)  NOT NULL DEFAULT 'UTC',
    password_changed_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    version             BIGINT       NOT NULL DEFAULT 0,
    CONSTRAINT users_email_key            UNIQUE (email),
    CONSTRAINT users_email_normalized_chk CHECK (
        email = lower(btrim(email))
        AND char_length(email) BETWEEN 3 AND 320
        AND position('@' IN email) > 1),
    CONSTRAINT users_display_name_chk     CHECK (char_length(btrim(display_name, E' \t\r\n')) BETWEEN 1 AND 100),
    CONSTRAINT users_timezone_chk         CHECK (char_length(timezone) BETWEEN 1 AND 64)
);

CREATE TRIGGER users_set_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- One row per issued refresh token. Only a SHA-256 hex digest of the token is
-- stored, so a database leak does not expose usable tokens.
-- Rotation: each refresh revokes the presented row (reason ROTATED) and issues a
-- new row in the same family_id; presenting an already-rotated token lets the
-- application revoke the whole family (REUSE_DETECTED).
CREATE TABLE refresh_sessions (
    id             UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        UUID         NOT NULL,
    family_id      UUID         NOT NULL,
    token_hash     VARCHAR(64)  NOT NULL,
    issued_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    expires_at     TIMESTAMPTZ  NOT NULL,
    revoked_at     TIMESTAMPTZ,
    revoked_reason VARCHAR(30),
    replaced_by    UUID,
    user_agent     VARCHAR(255),
    CONSTRAINT refresh_sessions_user_fk        FOREIGN KEY (user_id)     REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT refresh_sessions_replaced_by_fk FOREIGN KEY (replaced_by) REFERENCES refresh_sessions (id) ON DELETE SET NULL,
    CONSTRAINT refresh_sessions_token_hash_key UNIQUE (token_hash),
    CONSTRAINT refresh_sessions_token_hash_chk CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT refresh_sessions_expiry_chk     CHECK (expires_at > issued_at),
    CONSTRAINT refresh_sessions_revocation_chk CHECK (
        (revoked_at IS NULL AND revoked_reason IS NULL) OR revoked_at IS NOT NULL),
    CONSTRAINT refresh_sessions_reason_chk     CHECK (
        revoked_reason IS NULL OR revoked_reason IN
        ('LOGOUT', 'ROTATED', 'REUSE_DETECTED', 'PASSWORD_CHANGE', 'ACCOUNT_DELETION', 'ADMIN'))
);

CREATE INDEX refresh_sessions_user_idx    ON refresh_sessions (user_id);
-- Fast "list / revoke all active sessions for a user".
CREATE INDEX refresh_sessions_active_idx  ON refresh_sessions (user_id) WHERE revoked_at IS NULL;
-- Supports periodic cleanup of expired rows.
CREATE INDEX refresh_sessions_expires_idx ON refresh_sessions (expires_at);

CREATE TABLE user_preferences (
    user_id    UUID        PRIMARY KEY,
    theme      VARCHAR(10) NOT NULL DEFAULT 'system',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    version    BIGINT      NOT NULL DEFAULT 0,
    CONSTRAINT user_preferences_user_fk  FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT user_preferences_theme_chk CHECK (theme IN ('light', 'dark', 'system'))
);

CREATE TRIGGER user_preferences_set_updated_at
    BEFORE UPDATE ON user_preferences
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Append-only log of consent decisions; the latest row per (user, type) wins.
CREATE TABLE consent_records (
    id             UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id        UUID        NOT NULL,
    consent_type   VARCHAR(40) NOT NULL,
    granted        BOOLEAN     NOT NULL,
    policy_version VARCHAR(20) NOT NULL,
    recorded_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT consent_records_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE,
    CONSTRAINT consent_records_type_chk CHECK (consent_type IN
        ('PRIVACY_NOTICE_ACK', 'WELLNESS_DISCLAIMER_ACK', 'OPTIONAL_USAGE_ANALYTICS')),
    CONSTRAINT consent_records_policy_version_chk CHECK (char_length(policy_version) BETWEEN 1 AND 20)
);

CREATE INDEX consent_records_user_type_idx ON consent_records (user_id, consent_type, recorded_at DESC);
